# Try each column/row spreading X steps max
def limited_spread(grid, max_steps=8):
    result = [row[:] for row in grid]

    # Spread columns
    for c in range(21):
        fours = [r for r in range(25) if result[r][c] == 4]
        if fours:
            min_r = min(fours)
            max_r = max(fours)
            for r in range(min_r - 1, -1, -1):
                if result[r][c] == 0:
                    result[r][c] = 4

            for r in range(min_r + 1, 25):
                if result[r][c] == 0 and r <= min_r + max_steps:
                    result[r][c] = 4

    # Spread rows
    for r in range(25):
        fours = [c for c in range(21) if result[r][c] == 4]
        if fours:
            min_c = min(fours)
            max_c = max(fours)
            for c in range(min_c - 1, -1, -1):
                if result[r][c] == 0 and c <= min_c + max_steps:
                    result[r][c] = 4
            for c in range(max_c + 1, 21):
                if result[r][c] == 0 and c <= max_c + max_steps:
                    result[r][c] = 4

    return result

